import { SESSION_TTL_SECONDS } from '../config';

export function touch(store: Store, id: string) {
    return store.expire(id, SESSION_TTL_SECONDS);
}

export class SessionExpired extends Error {
    readonly code = 'SESSION_EXPIRED';
    readonly status = 401;
}

