const MAX_RETRIES = 5;
const RETRY_DELAY_MS = 2000;

export async function push(file: string) {
    for (let attempt = 0; attempt <= MAX_RETRIES; attempt++) {
        if (await tryUpload(file)) return;
        await sleep(RETRY_DELAY_MS);
    }
    throw new Error('Upload failed');
}
